UPDATE budget.tbudget_type SET template_transaction_id = NULL;

DELETE FROM budget.ttransaction_detail;
DELETE FROM budget.ttransaction;

DELETE FROM budget.tbudget_type_pyramid_level
WHERE budget_type_id IN (SELECT id FROM budget.tbudget_type WHERE household_id IS NOT NULL);

DELETE FROM budget.tbudget_type WHERE household_id IS NOT NULL;

DELETE FROM budget.ttemplate_transaction_det
WHERE template_transaction_id IN (
    SELECT id FROM budget.ttemplate_transaction WHERE household_id IS NOT NULL
);
DELETE FROM budget.ttemplate_transaction WHERE household_id IS NOT NULL;

DELETE FROM budget.tfinancial_pyramid_level
WHERE financial_pyramid_id IN (
    SELECT id FROM budget.tfinancial_pyramid WHERE household_id IS NOT NULL
);
DELETE FROM budget.tfinancial_pyramid WHERE household_id IS NOT NULL;

DELETE FROM budget.taccount WHERE household_id IS NOT NULL;
DELETE FROM budget.tauxiliar WHERE household_id IS NOT NULL;
DELETE FROM budget.thousehold_member;
DELETE FROM budget.thousehold;

DELETE FROM budget.ttemplate_transaction_det
WHERE template_transaction_id IN (
    SELECT id FROM budget.ttemplate_transaction WHERE household_id IS NULL
);
DELETE FROM budget.ttemplate_transaction WHERE household_id IS NULL;


