INSERT INTO budget.ttemplate_transaction (
    id, business_type_id, household_id, code, name, version, description, input_schema, created_by, status
) VALUES
    ('113220eb-ab64-472a-86bb-f44414fd498f', 'e1d42022-fca8-43f2-a37d-7823372fddb0', null, 'account_transfer', 'Transfer Between Own Accounts', 1, 'Same currency and household; source differs from destination. Savings and withdrawals are neither expenses nor income.', '{"type":"object","required":["amount","source_account_id","destination_account_id"],"additionalProperties":false,"properties":{"amount":{"type":"number","exclusiveMinimum":0},"source_account_id":{"type":"string","format":"uuid","x-allowed-account-codes":["110","111","112"],"x-household":"current","x-postable":true},"destination_account_id":{"type":"string","format":"uuid","x-allowed-account-codes":["110","111","112"],"x-household":"current","x-postable":true}},"x-validation-rules":[],"x-domain-note":"Same currency and household; source differs from destination. Savings and withdrawals are neither expenses nor income."}'::jsonb, '6f521862-f9dd-450a-ab69-79de338e2269', 'active'),
    ('4490f007-85b4-4307-818d-1213ade9080b', 'e1d42022-fca8-43f2-a37d-7823372fddb0', null, 'asset_purchase', 'Buy a Vehicle with Own Funds', 1, 'The purchase creates an asset. Routine maintenance remains an expense.', '{"type":"object","required":["amount","payment_account_id","asset_auxiliary_id"],"additionalProperties":false,"properties":{"amount":{"type":"number","exclusiveMinimum":0},"payment_account_id":{"type":"string","format":"uuid","x-allowed-account-codes":["110","111","112"],"x-household":"current","x-postable":true},"asset_auxiliary_id":{"type":"string","format":"uuid","x-household":"current"}},"x-validation-rules":[],"x-domain-note":"The purchase creates an asset. Routine maintenance remains an expense."}'::jsonb, '6f521862-f9dd-450a-ab69-79de338e2269', 'active'),
    ('18ff4e41-4f0d-4abe-ae50-f90f0ce80fe9', 'e1d42022-fca8-43f2-a37d-7823372fddb0', null, 'asset_purchase_financed', 'Buy a Vehicle with Direct Bank Financing', 1, 'Use when the lender pays the seller directly. If funds first reach the family bank account, record loan receipt and a separate asset purchase; do not post both workflows.', '{"type":"object","required":["price","down_payment","financed_principal","payment_account_id","asset_auxiliary_id","loan_auxiliary_id"],"additionalProperties":false,"properties":{"price":{"type":"number","exclusiveMinimum":0},"down_payment":{"type":"number","minimum":0},"financed_principal":{"type":"number","exclusiveMinimum":0},"payment_account_id":{"type":"string","format":"uuid","x-allowed-account-codes":["110","111","112"],"x-household":"current","x-postable":true},"asset_auxiliary_id":{"type":"string","format":"uuid","x-household":"current"},"loan_auxiliary_id":{"type":"string","format":"uuid","x-household":"current"}},"x-validation-rules":["financed_price"],"x-domain-note":"Use when the lender pays the seller directly. If funds first reach the family bank account, record loan receipt and a separate asset purchase; do not post both workflows."}'::jsonb, '6f521862-f9dd-450a-ab69-79de338e2269', 'active'),
    ('02f49765-48c0-4aa4-92d6-d0e60a7215b8', 'e1d42022-fca8-43f2-a37d-7823372fddb0', null, 'asset_sale', 'Sell a Vehicle', 1, 'Compute gain/loss from proceeds minus carrying value; never recognize both. Zero lines are omitted.', '{"type":"object","required":["proceeds","carrying_cost","gain","loss","receipt_account_id","asset_auxiliary_id"],"additionalProperties":false,"properties":{"proceeds":{"type":"number","minimum":0},"carrying_cost":{"type":"number","exclusiveMinimum":0},"gain":{"type":"number","minimum":0},"loss":{"type":"number","minimum":0},"receipt_account_id":{"type":"string","format":"uuid","x-allowed-account-codes":["110","111","112"],"x-household":"current","x-postable":true},"asset_auxiliary_id":{"type":"string","format":"uuid","x-household":"current"}},"x-validation-rules":["sale_result"],"x-domain-note":"Compute gain/loss from proceeds minus carrying value; never recognize both. Zero lines are omitted."}'::jsonb, '6f521862-f9dd-450a-ab69-79de338e2269', 'active'),
    ('49feb73b-2147-441a-8a2d-a1d002ccfe2a', 'e1d42022-fca8-43f2-a37d-7823372fddb0', null, 'asset_write_down', 'Record Vehicle Depreciation', 1, 'Simplified direct reduction of carrying value for family reporting, not a tax depreciation schedule. Amount cannot exceed carrying value.', '{"type":"object","required":["amount","asset_auxiliary_id"],"additionalProperties":false,"properties":{"amount":{"type":"number","exclusiveMinimum":0},"asset_auxiliary_id":{"type":"string","format":"uuid","x-household":"current"}},"x-validation-rules":[],"x-domain-note":"Simplified direct reduction of carrying value for family reporting, not a tax depreciation schedule. Amount cannot exceed carrying value."}'::jsonb, '6f521862-f9dd-450a-ab69-79de338e2269', 'active'),
    ('1d92c268-6cc3-4210-9bfc-655e333c9fab', 'e1d42022-fca8-43f2-a37d-7823372fddb0', null, 'bill_payment', 'Pay a Previously Recorded Bill', 1, 'Do not recognize the expense again; payment cannot exceed unpaid balance.', '{"type":"object","required":["amount","payment_account_id","supplier_auxiliary_id"],"additionalProperties":false,"properties":{"amount":{"type":"number","exclusiveMinimum":0},"payment_account_id":{"type":"string","format":"uuid","x-allowed-account-codes":["110","111","112"],"x-household":"current","x-postable":true},"supplier_auxiliary_id":{"type":"string","format":"uuid","x-household":"current"}},"x-validation-rules":[],"x-domain-note":"Do not recognize the expense again; payment cannot exceed unpaid balance."}'::jsonb, '6f521862-f9dd-450a-ab69-79de338e2269', 'active'),
    ('477656a2-5334-4853-95c1-caf51f7ef15a', 'e1d42022-fca8-43f2-a37d-7823372fddb0', null, 'borrow_interest_bearing', 'Borrow Money — Interest Bearing', 1, 'Principal must be positive. Require the loan-specific auxiliary. Confirm principal and interest allocation from the agreement. Interest-free and interest-bearing originations share accounting but represent different contract flows.', '{"type":"object","required":["principal","cash_account_id","counterparty_id","loan_reference"],"additionalProperties":false,"properties":{"principal":{"type":"number","exclusiveMinimum":0},"cash_account_id":{"type":"string","format":"uuid","x-allowed-account-codes":["110","111","112"],"x-household":"current","x-postable":true},"counterparty_id":{"type":"string","format":"uuid","x-household":"current"},"loan_reference":{"type":"string","minLength":1}},"x-validation-rules":["principal_positive","principal_not_above_outstanding_on_repayment"],"x-domain-note":"Principal must be positive. Require the loan-specific auxiliary. Confirm principal and interest allocation from the agreement. Interest-free and interest-bearing originations share accounting but represent different contract flows."}'::jsonb, '6f521862-f9dd-450a-ab69-79de338e2269', 'active'),
    ('20fd4336-eb8c-4245-baf2-ed71fca0a51b', 'e1d42022-fca8-43f2-a37d-7823372fddb0', null, 'borrow_interest_free', 'Borrow Money — Interest Free', 1, 'Principal must be positive. Require the loan-specific auxiliary. Confirm principal and interest allocation from the agreement. Interest-free and interest-bearing originations share accounting but represent different contract flows.', '{"type":"object","required":["principal","cash_account_id","counterparty_id","loan_reference"],"additionalProperties":false,"properties":{"principal":{"type":"number","exclusiveMinimum":0},"cash_account_id":{"type":"string","format":"uuid","x-allowed-account-codes":["110","111","112"],"x-household":"current","x-postable":true},"counterparty_id":{"type":"string","format":"uuid","x-household":"current"},"loan_reference":{"type":"string","minLength":1}},"x-validation-rules":["principal_positive","principal_not_above_outstanding_on_repayment"],"x-domain-note":"Principal must be positive. Require the loan-specific auxiliary. Confirm principal and interest allocation from the agreement. Interest-free and interest-bearing originations share accounting but represent different contract flows."}'::jsonb, '6f521862-f9dd-450a-ab69-79de338e2269', 'active'),
